import{_ as a,o,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Lei de Proteção Ambiental","description":"","frontmatter":{},"headers":[],"relativePath":"pt/46-环境保护法.md","filePath":"pt/46-环境保护法.md"}'),d={name:"pt/46-环境保护法.md"};function r(s,e,n,l,c,m){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="lei-de-protecao-ambiental" tabindex="-1">Lei de Proteção Ambiental <a class="header-anchor" href="#lei-de-protecao-ambiental" aria-label="Permalink to &quot;Lei de Proteção Ambiental&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>46</td></tr><tr><td>Módulo</td><td>Sistema Jurídico e Estrutura de Governança</td></tr><tr><td>Palavras-chave principais</td><td>Proteção Ambiental, Origem do Universo, Simbiose Ecológica, Desenvolvimento Sustentável, Prevenção e Controle da Poluição</td></tr></tbody></table><h2 id="i-objetivo-legislativo-e-principios-fundamentais" tabindex="-1">I. Objetivo Legislativo e Princípios Fundamentais <a class="header-anchor" href="#i-objetivo-legislativo-e-principios-fundamentais" aria-label="Permalink to &quot;I. Objetivo Legislativo e Princípios Fundamentais&quot;">​</a></h2><p>A 《Lei de Proteção Ambiental》 é uma das cinco leis complementares da civilização simbiótica de âncoras, visando proteger o ambiente ecológico e a origem do universo de Hengyuanzhou, estabelecer o conceito de governança ambiental de &quot;evolução simbiótica, desenvolvimento sustentável&quot;, prevenir a destruição do ecossistema do universo causada pela exploração predatória, e proteger a base de sobrevivência para o progresso comum de todas as raças.</p><p>Esta lei estabelece os seguintes princípios fundamentais:</p><table tabindex="0"><thead><tr><th>Princípio</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Princípio da Proteção da Origem</td><td>A origem do universo é a base de toda vida e evolução, deve ser protegida com prioridade, e a exploração destrutiva é proibida</td></tr><tr><td>Princípio da Simbiose Ecológica</td><td>Humanos e natureza, cada raça e ecossistema estão em relação simbiótica, e destruir a ecologia é destruir a própria base de sobrevivência</td></tr><tr><td>Princípio da Sustentabilidade</td><td>Todas as atividades de exploração devem levar em conta os interesses das gerações presentes e futuras, opondo-se à exploração excessiva</td></tr><tr><td>Princípio da Prevenção como Principal</td><td>A proteção ambiental prioriza a prevenção, estabelece o sistema de avaliação de impacto ambiental e previne a ocorrência de poluição</td></tr><tr><td>Princípio da Responsabilidade do Poluidor</td><td>O sujeito que causa poluição ambiental e destruição ecológica deve assumir a responsabilidade de tratamento e indenização</td></tr><tr><td>Princípio da Participação Pública</td><td>Incentivar a participação pública na proteção ambiental, garantindo o direito do público à informação ambiental e à participação</td></tr><tr><td>Princípio da Cooperação Inter-Planos</td><td>A proteção ambiental avança por meio da cooperação inter-planos, estabelecendo mecanismos de cooperação para governança ambiental inter-planos</td></tr></tbody></table><h2 id="ii-escopo-da-protecao-ambiental" tabindex="-1">II. Escopo da Proteção Ambiental <a class="header-anchor" href="#ii-escopo-da-protecao-ambiental" aria-label="Permalink to &quot;II. Escopo da Proteção Ambiental&quot;">​</a></h2><p>O escopo ambiental protegido por esta lei inclui todos os ecossistemas e elementos ambientais dentro de Hengyuanzhou:</p><ol><li><strong>Ambiente Atmosférico</strong>: Inclui a atmosfera de cada planeta, a concentração de energia e o equilíbrio de composição das camadas de energia.</li><li><strong>Ambiente Hídrico</strong>: Inclui a qualidade e quantidade de água de águas superficiais, águas subterrâneas, oceanos e corpos d&#39;água de energia entre planos.</li><li><strong>Ambiente do Solo</strong>: Inclui a qualidade e fertilidade do solo terrestre e dos veios de minério de recursos de cultivo.</li><li><strong>Biodiversidade</strong>: Inclui a proteção de espécies e habitats de todos os animais e plantas, microrganismos e vidas estranhas.</li><li><strong>Ambiente de Energia</strong>: Inclui a concentração e o equilíbrio de distribuição da energia espiritual do céu e da terra, energia de origem e fragmentos de leis.</li><li><strong>Ambiente Espacial</strong>: Inclui a estabilidade espacial dos planos, fissuras espaciais e segurança ambiental de espaços dobrados.</li><li><strong>Ambiente do Domínio da Consciência</strong>: Inclui a limpeza de informações do espaço de consciência coletiva e a prevenção e controle da poluição espiritual.</li></ol><h2 id="iii-principais-sistemas" tabindex="-1">III. Principais Sistemas <a class="header-anchor" href="#iii-principais-sistemas" aria-label="Permalink to &quot;III. Principais Sistemas&quot;">​</a></h2><h3 id="_1-sistema-de-avaliacao-de-impacto-ambiental" tabindex="-1">(1) Sistema de Avaliação de Impacto Ambiental <a class="header-anchor" href="#_1-sistema-de-avaliacao-de-impacto-ambiental" aria-label="Permalink to &quot;(1) Sistema de Avaliação de Impacto Ambiental&quot;">​</a></h3><p>Todos os projetos de desenvolvimento e construção que possam ter impacto significativo no meio ambiente devem passar por avaliação de impacto ambiental antes do início das obras. O conteúdo da avaliação inclui: o impacto do projeto nos elementos ambientais como atmosfera, água, solo, organismos, energia, espaço, etc., medidas de prevenção e mitigação, avaliação de riscos ambientais, etc. Projetos que não forem aprovados na avaliação de impacto ambiental não podem iniciar a construção.</p><h3 id="_2-sistema-de-licenciamento-de-poluicao-e-controle-de-quantidade-total" tabindex="-1">(2) Sistema de Licenciamento de Poluição e Controle de Quantidade Total <a class="header-anchor" href="#_2-sistema-de-licenciamento-de-poluicao-e-controle-de-quantidade-total" aria-label="Permalink to &quot;(2) Sistema de Licenciamento de Poluição e Controle de Quantidade Total&quot;">​</a></h3><p>O Estado implementa gestão de licenças e controle de quantidade total para a emissão de poluentes. As unidades de emissão de poluição devem obter a licença de emissão de poluição e emitir poluentes de acordo com os tipos, concentrações e quantidades totais especificados na licença. O Estado determina a quantidade total de emissão de poluentes de cada região e cada plano de acordo com a capacidade de suporte ambiental, e a decompõe e implementa passo a passo.</p><h3 id="_3-sistema-de-linha-vermelha-de-protecao-ecologica" tabindex="-1">(3) Sistema de Linha Vermelha de Proteção Ecológica <a class="header-anchor" href="#_3-sistema-de-linha-vermelha-de-protecao-ecologica" aria-label="Permalink to &quot;(3) Sistema de Linha Vermelha de Proteção Ecológica&quot;">​</a></h3><p>O Estado delimita linhas vermelhas de proteção ecológica em regiões com valor ecológico especial, incluindo:</p><table tabindex="0"><thead><tr><th>Tipo de Linha Vermelha</th><th>Conteúdo de Proteção</th></tr></thead><tbody><tr><td>Área de Proteção da Origem</td><td>Área central de produção de energia de origem do universo, todas as atividades de exploração são proibidas</td></tr><tr><td>Habitat de Espécies</td><td>Habitat central de espécies raras e ameaçadas de extinção, destruição e interferência são proibidas</td></tr><tr><td>Área de Barreira Ecológica</td><td>Ecossistema chave que mantém o equilíbrio ecológico regional, exploração é restrita</td></tr><tr><td>Terra Sagrada de Cultivo</td><td>Área rica em energia com valor especial de cultivo, implementa uso protetor</td></tr><tr><td>Zona de Fronteira de Planos</td><td>Zona de transição ecológica entre planos, exploração destrutiva espacial é proibida</td></tr></tbody></table><h3 id="_4-sistema-de-monitoramento-e-alerta-ambiental" tabindex="-1">(4) Sistema de Monitoramento e Alerta Ambiental <a class="header-anchor" href="#_4-sistema-de-monitoramento-e-alerta-ambiental" aria-label="Permalink to &quot;(4) Sistema de Monitoramento e Alerta Ambiental&quot;">​</a></h3><p>O Estado estabelece uma rede de monitoramento ambiental cobrindo todo o universo, monitorando em tempo real as mudanças de cada elemento ambiental. Para possíveis eventos graves de poluição ambiental e destruição ecológica, estabelece mecanismos de alerta, divulga informações de alerta em tempo hábil e inicia resposta de emergência.</p><h3 id="_5-sistema-de-compensacao-ecologica" tabindex="-1">(5) Sistema de Compensação Ecológica <a class="header-anchor" href="#_5-sistema-de-compensacao-ecologica" aria-label="Permalink to &quot;(5) Sistema de Compensação Ecológica&quot;">​</a></h3><p>Regiões e grupos cuja exploração é restringida devido à proteção ambiental têm o direito de receber compensação ecológica. Os fundos de compensação ecológica são arcados pela acumulação pública e pelos rendimentos da exploração de recursos, e são usados para o desenvolvimento econômico da região de compensação e a melhoria da vida dos residentes.</p><h2 id="iv-regulamentacao-ambiental-das-atividades-de-cultivo" tabindex="-1">IV. Regulamentação Ambiental das Atividades de Cultivo <a class="header-anchor" href="#iv-regulamentacao-ambiental-das-atividades-de-cultivo" aria-label="Permalink to &quot;IV. Regulamentação Ambiental das Atividades de Cultivo&quot;">​</a></h2><p>O impacto das atividades de cultivo no meio ambiente é uma área especial da proteção ambiental de Hengyuanzhou, e esta lei estabelece especificamente cláusulas de regulamentação:</p><ol><li><strong>Regulamentação da Exploração de Energia</strong>: A exploração de recursos de cultivo deve atender ao princípio da sustentabilidade, e a exploração destrutiva que leva ao esgotamento de energia é proibida. A quantidade de exploração não pode exceder a velocidade de recuperação natural da energia regional.</li><li><strong>Tratamento de Resíduos de Cultivo</strong>: Resíduos de energia, pílulas de cultivo descartadas, instrumentos danificados, etc., gerados durante o processo de cultivo devem ser tratados de acordo com as disposições, e o descarte aleatório que causa poluição de energia é proibido.</li><li><strong>Avaliação Ambiental de Cultivo Avançado</strong>: O avanço e o retiro de cultivadores avançados podem ter impacto significativo no ambiente circundante, e devem passar por avaliação ambiental antecipada e adotar medidas de proteção.</li><li><strong>Licença de Exploração de Planos</strong>: A exploração de novos planos deve passar por avaliação ambiental e investigação ecológica, e só pode ser realizada após a formulação de um plano de proteção ecológica.</li><li><strong>Proteção de Habitats de Vidas Estranhas</strong>: Os habitats de vidas estranhas são incluídos na linha vermelha de proteção ecológica, e a exploração e desenvolvimento sem licença são proibidos.</li></ol><h2 id="v-responsabilidade-juridica" tabindex="-1">V. Responsabilidade Jurídica <a class="header-anchor" href="#v-responsabilidade-juridica" aria-label="Permalink to &quot;V. Responsabilidade Jurídica&quot;">​</a></h2><p>Atividades que violam as disposições desta lei assumem as seguintes responsabilidades de acordo com a gravidade da infração:</p><ul><li>Iniciar obras sem aprovação na avaliação de impacto ambiental, ordenar a paralisação da construção, restaurar o estado original e impor multa.</li><li>Emitir poluentes acima do padrão, ordenar o tratamento dentro do prazo e impor multa, em casos graves ordenar o encerramento das atividades.</li><li>Destruir a linha vermelha de proteção ecológica, ordenar a restauração do estado original e impor multa, em casos graves追究 responsabilidade criminal.</li><li>Exploração destrutiva de recursos de cultivo, confiscar os ganhos ilegais e impor multa, revogar a licença de exploração.</li><li>Causar acidentes graves de poluição ambiental, assumir responsabilidade por indenização, se constituir crime追究 responsabilidade criminal.</li><li>Pessoal de supervisão ambiental que negligencia suas funções ou abusa de seu poder, aplicar punição, se constituir crime追究 responsabilidade criminal.</li></ul><h2 id="vi-participacao-publica-e-acao-civil-publica-ambiental" tabindex="-1">VI. Participação Pública e Ação Civil Pública Ambiental <a class="header-anchor" href="#vi-participacao-publica-e-acao-civil-publica-ambiental" aria-label="Permalink to &quot;VI. Participação Pública e Ação Civil Pública Ambiental&quot;">​</a></h2><p>O público tem o direito de participar da proteção ambiental, e os canais específicos incluem:</p><ol><li>Apresentar opiniões e sugestões sobre projetos de avaliação de impacto ambiental.</li><li>Denunciar e reclamar sobre comportamentos que poluem o meio ambiente e destroem a ecologia.</li><li>Estabelecer organizações de proteção ambiental de acordo com a lei, participar da supervisão ambiental e de atividades de bem público.</li><li>Para comportamentos que poluem o meio ambiente e destroem a ecologia, prejudicando o interesse público, as organizações de proteção ambiental podem entrar com ação civil pública ambiental no Tribunal Simbiótico.</li></ol><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A 《Lei de Proteção Ambiental》 é a garantia jurídica do conceito de desenvolvimento sustentável da civilização simbiótica de âncoras. Ao estabelecer sistemas como avaliação de impacto ambiental, linha vermelha de proteção ecológica e controle de quantidade total, ela integra a proteção ambiental em todas as atividades de exploração e cultivo, garante a sustentabilidade da origem do universo e do ecossistema, e protege a eterna base de sobrevivência para o progresso comum de todas as raças.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Princípios Gerais da Constituição Simbiótica)</li><li>39-住房与环境保障 (Garantia de Habitação e Ambiente)</li><li>15-能量循环与转化法则 (Lei do Ciclo e Transformação de Energia)</li><li>53-奇特生命识别标准 (Padrão de Identificação de Vidas Estranhas)</li></ul>',34)])])}const b=a(d,[["render",r]]);export{u as __pageData,b as default};
